class stringx
{
public:
  char* chars;
  void* my_buf;

  stringx(const char*);
  ~stringx();
  stringx& operator=(const stringx&);
  stringx& operator+=(const stringx&);
};

class filespec
{
public:
  stringx path;
  stringx name;
  stringx ext;

  explicit filespec(const stringx&);
};

class anim_texture
{
  char data[48];

public:
  unsigned get_blend_mode() const;
  const stringx& get_filename();
};

enum
{
  MAPS_PER_MATERIAL = 4
};

class material
{
  void build_hash_name();

public:
  stringx material_name;
  stringx texture_filename[MAPS_PER_MATERIAL];
  anim_texture diffuse_map[MAPS_PER_MATERIAL];
  float u_anim;
  float v_anim;
  float det_u_scale;
  float det_v_scale;
  float det_range;
  float det_alpha_clamp;
  unsigned mat_flags;
};

void material::build_hash_name()
{
  filespec fspec( texture_filename[0] );
  material_name = fspec.name;
  int i;
  for( i=1;i<MAPS_PER_MATERIAL;i++ )
  {
    material_name += diffuse_map[i].get_filename();
  }

  // Build hash string to append to name.  All numerical values mashed into 8 char string.
  char hasher_string[9] = "12345678";
  float float_hash;
  unsigned int hash;
  float_hash = 2 * mat_flags +
               3 * u_anim +
               5 * v_anim +
               7 * diffuse_map[0].get_blend_mode();
  // bash it to an unsigned int
  hash = *((unsigned int*) &float_hash);

  unsigned int mask = 0x0000000F;
  int shifter = 0;
  for (i=0;i<8;++i)
  {
    hasher_string[i] = 'A' + ((hash&mask)>>shifter);
    shifter+=4;
    mask<<=4;
  }

  // And slap it on
  material_name += stringx(hasher_string);
}
